  document.addEventListener('visibilitychange',()=>{if(document.hidden)endReveal();});document.addEventListener('close',event=>{if(event.target.id==='home-dialog')endReveal();},true);
  window.addEventListener('voidline:activity',event=>{identity();const update=event.detail;if(accountId&&update?.accountId===accountId&&Number.isSafeInteger(update.giftRequests)&&update.giftRequests>=0)pending=update.giftRequests;});
