  document.addEventListener('change',event=>{const input=event.target;if(!state().account)return;if(input.hasAttribute('data-vc-kind')){kindFilter=['all','badge','gift'].includes(input.value)?input.value:'all';badgeFilter='all';paintBrowse();return;}if(input.hasAttribute('data-vc-series')){seriesFilter=input.value;paintBrowse();return;}if(input.hasAttribute('data-vc-instance-filter')){inventoryPanel(0,input.value).catch(errorNode);return;}if(input.hasAttribute('data-vc-setting'))mutate('/settings',{giftsEnabled:input.checked},input,()=>app.announce(input.checked?'Gift requests enabled.':'Gift requests disabled.')).finally(()=>{if(input.isConnected)input.checked=giftsEnabled;});});
